SELECT bpmol.occur_log_id occurLogId, bpmol.occur_date occurDate, bpt.NAME, bpt.mobile, bpm.member_level_id memberLevelId, bpm.member_level_name memberLevelName, bpm.card_number cardNumber, bpmol.principal_amount principalAmount, bpmol.bonus_amount bonusAmount, bpmol.current_recharge_principal currentRechargePrincipal, bpmol.current_recharge_bonus currentRechargeBonus, bpmol.payment_id paymentId, bpmol.payment_manner paymentManner, bpmol.operator_user_id, (select be.employee_name from base_employee be where be.user_id = bpmol.operator_user_id) operatorUserName, bpmol.remarks FROM base_patient_member_occur_log bpmol JOIN base_patient bpt ON bpmol.patient_id = bpt.patient_Id JOIN base_patient_member bpm ON bpm.patient_id = bpt.patient_Id
bpmol.type = 0 AND bpmol.occur_type = 1
AND bpmol.org_id = #{form.orgId}
AND bpm.card_number = #{form.cardNumber}
AND bpmol.patient_id in
#{ids}
AND bpm.member_level_id in
#{levelIds}
and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') >= DATE_FORMAT(#{form.startDate}, '%Y-%m-%d') and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') < DATE_FORMAT(#{form.endDate}, '%Y-%m-%d')
group by bpmol.occur_date desc

SELECT bpmol.occur_log_id occurLogId, bpmol.occur_date occurDate, bb.order_date orderDate, bb.order_num orderNum, bpt.NAME, bpt.mobile, ( SELECT NAME FROM base_patient WHERE patient_id = bpm.patient_id ) masterCardName, bpm.card_number cardNumber, bpm.member_level_id memberLevelId, bpm.member_level_name memberLevelName, bpmol.principal_amount principalAmount, bpmol.bonus_amount bonusAmount, bpmol.current_recharge_principal currentRechargePrincipal, bpmol.current_recharge_bonus currentRechargeBonus, bpmol.remarks FROM base_patient_member_occur_log bpmol JOIN base_patient bpt ON bpmol.patient_id = bpt.patient_Id JOIN base_patient_member bpm ON bpm.card_id = bpmol.card_id JOIN base_bill bb ON bpmol.bill_id = bb.bill_id
bpmol.type = 0 AND bpmol.occur_type = 2
AND bpmol.org_id = #{form.orgId}
AND bpm.card_number = #{form.cardNumber}
AND bpmol.patient_id in
#{ids}
AND bpm.member_level_id in
#{levelIds}
and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') >= DATE_FORMAT(#{form.startDate}, '%Y-%m-%d') and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') < DATE_FORMAT(#{form.endDate}, '%Y-%m-%d')
group by bpmol.occur_date desc

